import {
  DoubleSide, Group, InstancedMesh, MeshStandardMaterial, Object3D, PlaneGeometry, SRGBColorSpace,
  TextureLoader,
} from "three";

// Generated by scripts/pack-tree-atlas.py from front-view renders of Poly Haven trees.
const TREE_ATLAS = {
  jacaranda: { u: 0.0000, v: 0.5010, width: 0.6221, height: 0.4990, aspect: 1.254 },
  slender: { u: 0.6240, v: 0.5010, width: 0.3174, height: 0.4990, aspect: 0.640 },
  broad: { u: 0.0000, v: 0.0000, width: 0.4688, height: 0.4990, aspect: 0.945 },
  shrub: { u: 0.4707, v: 0.2495, width: 0.1914, height: 0.2495, aspect: 0.772 },
  shrubWide: { u: 0.6641, v: 0.2495, width: 0.2227, height: 0.2495, aspect: 0.898 },
};
type TreeVariant = keyof typeof TREE_ATLAS;
// x, z, height, variant; a negative height shows the cutout's mirrored back face for variety.
type Placement = [number, number, number, TreeVariant];

const STREET_PLANTING: Placement[] = [
  // Yard trees beside the houses across the street.
  [-7, -23, 8, "broad"], [13, -31, 11, "jacaranda"], [-12.5, -33, -10, "jacaranda"], [-1.8, -33.5, 9.5, "slender"],
  // Foundation shrubs along the house fronts.
  [0.6, -24.6, 1.3, "shrubWide"], [2.1, -24.7, -1.1, "shrub"], [7.4, -24.6, 1.2, "shrub"], [9.2, -24.7, -1.3, "shrubWide"],
  [-13.2, -27.3, 1.2, "shrub"], [-18.6, -27.2, -1.3, "shrubWide"],
];
const VARIANTS: TreeVariant[] = ["jacaranda", "broad", "slender"];
// Staggered heights and mirrored variants break up the skyline; a smaller front row
// covers the gaps between taller trunks without a flat backdrop plane.
for (let i = 0; i < 15; i++) {
  STREET_PLANTING.push([-42 + i * 6, -46 - (i % 3) * 2, (10 + (i * 7 % 4)) * (i % 2 ? -1 : 1), VARIANTS[i % 3]]);
}
for (let i = 0; i < 17; i++) {
  STREET_PLANTING.push([-40 + i * 5, -38 - (i % 3), (6 + (i * 3 % 4) * 0.6) * (i % 3 ? 1 : -1), VARIANTS[(i + 1) % 3]]);
}

/** Instanced cutout quads: one draw per variant, every tree sharing one atlas texture. */
export async function createGarageTrees(url: string, groundY: number, planting = STREET_PLANTING) {
  const texture = await new TextureLoader().loadAsync(url);
  texture.colorSpace = SRGBColorSpace;
  texture.anisotropy = 4;
  const material = new MeshStandardMaterial({
    map: texture, alphaTest: 0.5, alphaToCoverage: true, side: DoubleSide, roughness: 1, envMapIntensity: 2,
    // The street is backlit at dusk; a trace of the leaves' own colour keeps them from reading as black.
    emissive: "#ffffff", emissiveMap: texture, emissiveIntensity: 0.1,
  });
  const group = new Group();
  group.name = "GarageTrees";
  const transform = new Object3D();
  const batches: InstancedMesh[] = [];
  for (const [variant, rect] of Object.entries(TREE_ATLAS) as [TreeVariant, typeof TREE_ATLAS[TreeVariant]][]) {
    const placements = planting.filter(placement => placement[3] === variant);
    if (placements.length === 0) continue;
    // A unit-height quad whose base sits on the trunk's lowest texel.
    const geometry = new PlaneGeometry(rect.aspect, 1).translate(0, 0.5, 0);
    const uv = geometry.getAttribute("uv");
    for (let i = 0; i < uv.count; i++) {
      uv.setXY(i, rect.u + uv.getX(i) * rect.width, rect.v + uv.getY(i) * rect.height);
    }
    const batch = new InstancedMesh(geometry, material, placements.length);
    batch.name = `GarageTrees-${variant}`;
    placements.forEach(([x, z, height], index) => {
      transform.position.set(x, groundY - 0.04, z);
      // Turning a quad around (not a negative scale) keeps its lit side facing the street.
      transform.rotation.y = height < 0 ? Math.PI : 0;
      transform.scale.setScalar(Math.abs(height));
      transform.updateMatrix();
      batch.setMatrixAt(index, transform.matrix);
    });
    batch.instanceMatrix.needsUpdate = true;
    batch.computeBoundingSphere();
    group.add(batch);
    batches.push(batch);
  }
  return {
    group,
    dispose() {
      batches.forEach(batch => {
        batch.geometry.dispose();
        batch.dispose();
      });
      material.dispose();
      texture.dispose();
    },
  };
}
